#include <algorithm>
#include <fstream>
#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;class Person{protected:int id;string name;public:Person(int i,string n):id(i),name(move(n)){}virtual~Person()=default;int getId()const{return id;}const string&getName()const{return name;}};class MedicalRecord{vector<string>entries;public:void add(string d,string p){entries.push_back("Diagnosis: "+d+" | Rx: "+p);}void show()const{for(auto&e:entries)cout<<e<<'\n';}};class Patient:public Person{MedicalRecord rec;public:using Person::Person;MedicalRecord&medical(){return rec;}};class Doctor:public Person{string department;public:Doctor(int i,string n,string d):Person(i,move(n)),department(move(d)){}const string&dept()const{return department;}};struct Appointment{int id,pid,did;string date,time;};class Hospital{vector<Patient>patients;vector<Doctor>doctors;vector<Appointment>apps;int next=1;Patient*p(int id){for(auto&x:patients)if(x.getId()==id)return&x;return nullptr;}Doctor*d(int id){for(auto&x:doctors)if(x.getId()==id)return&x;return nullptr;}bool conflict(int did,string date,string time)const{for(auto&a:apps)if(a.did==did&&a.date==date&&a.time==time)return true;return false;}public:void addPatient(){int id;string n;cin>>id;cin>>ws;getline(cin,n);if(!p(id))patients.emplace_back(id,n);}void addDoctor(){int id;string n,dep;cin>>id;cin>>ws;getline(cin,n);getline(cin,dep);if(!d(id))doctors.emplace_back(id,n,dep);}void schedule(){int pid,did;string date,time;cin>>pid>>did>>date>>time;if(p(pid)&&d(did)&&!conflict(did,date,time))apps.push_back({next++,pid,did,date,time});else cout<<"Invalid/conflict\n";}void record(){int pid;string diag,rx;cin>>pid;auto*x=p(pid);if(!x)return;cin>>ws;getline(cin,diag);getline(cin,rx);x->medical().add(diag,rx);ofstream("medical_records.txt",ios::app)<<pid<<'|'<<diag<<'|'<<rx<<'\n';}void history(){int id;cin>>id;if(auto*x=p(id)){cout<<x->getName()<<'\n';x->medical().show();}}void report()const{map<int,int>count;for(auto&a:apps)count[a.did]++;for(auto&x:doctors)cout<<x.getName()<<" ("<<x.dept()<<"): "<<count[x.getId()]<<'\n';}void run(){for(;;){cout<<"\nHospital 2\n1 Patient 2 Doctor 3 Appointment 4 Medical record 5 History 6 Report 0 Exit\n";int c;if(!(cin>>c)||c==0)break;if(c==1)addPatient();else if(c==2)addDoctor();else if(c==3)schedule();else if(c==4)record();else if(c==5)history();else if(c==6)report();}}};int main(){Hospital{}.run();}
